// db.query(`SELECT * FROM users WHERE id = ${req.params.id}`)  ← INJECTION

// Do this instead (pg example):
const getUserById = async (id) => {
  const { rows } = await db.query('SELECT id, name FROM users WHERE id = $1', [id]);
