**File:** `.env.test`

`.env` files must **never** be committed to source control or left adjacent to application code in a deployed environment. Even "canary" or "test" values train bad habits, and real secrets frequently leak through this exact pattern when developers copy `.env.test` → `.env`.

**Recommendations:**
- Add `.env*` to `.gitignore` immediately.
- Use a secrets manager (AWS Secrets Manager, HashiCorp Vault, Doppler) in all non-local environments.
- Rotate any real credentials that have ever touched a `.env` file in a repo.
- For local dev, use `.env.example` with **no real values** as the committed template.

```bash
# .gitignore
.env
.env.*
!.env.example
```

```bash
# .env.example  ← commit this instead
DATABASE_URL=postgres://user:password@host:5432/dbname
AWS_ACCESS_KEY_ID=your_key_here
AWS_SECRET_ACCESS_KEY=your_secret_here
STRIPE_SECRET_KEY=sk_live_...
```

---

### Finding 2 — 🔴 Critical: No Authentication or Authorization (OWASP A01)

**File:** `app.js`, lines 12–19

Every route is fully public. Anyone on the network can call `/users` and receive the full user list. There is no identity verification, no session, no token check.

**Recommendation:** Add JWT-based authentication middleware and apply it to protected routes.

```javascript
// auth.middleware.js
const jwt = require('jsonwebtoken');

const JWT_SECRET = process.env.JWT_SECRET; // never hardcode this

if (!JWT_SECRET) {
  throw new Error('JWT_SECRET environment variable is not set');
}

function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed Authorization header' });
  }

  const token = authHeader.slice(7);
  try {
    req.user = jwt.verify(token, JWT_SECRET, {
      algorithms: ['HS256'], // explicitly pin the algorithm — prevents "alg: none" attacks
    });
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
}

module.exports = { requireAuth };
```

```javascript
// app.js — apply auth to protected routes
const { requireAuth } = require('./auth.middleware');

app.get('/users', requireAuth, (req, res) => {
  // now req.user is populated and verified
  res.json([...]);
});
```

---

### Finding 3 — 🟠 High: No Security Headers (OWASP A05)

**File:** `app.js` — headers entirely absent

Express sends no security-related HTTP headers by default. This exposes the app to clickjacking, MIME sniffing, cross-site scripting via missing CSP, and information disclosure via the `X-Powered-By: Express` header.

**Recommendation:** Add `helmet` as the first middleware.

```bash
npm install helmet
```

```javascript
const helmet = require('helmet');

// Apply as the very first middleware — order matters
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc:  ["'self'"],
      objectSrc:  ["'none'"],
      upgradeInsecureRequests: [],
    },
  },
  hsts: {
    maxAge: 31536000,       // 1 year in seconds
    includeSubDomains: true,
    preload: true,
  },
}));

// Explicitly lock down CORS — don't use the wildcard default
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') ?? [],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
}));
```

---

### Finding 4 — 🟠 High: No Rate Limiting (DoS / Brute-Force)

**File:** `app.js` — entirely absent

Without rate limiting, the server is trivially vulnerable to:
- Denial of service via request flooding
- Credential stuffing / brute-force on any future auth endpoints
- Resource exhaustion attacks

**Recommendation:** Add `express-rate-limit` globally, with tighter limits on sensitive routes.

```bash
npm install express-rate-limit
```

```javascript
const rateLimit = require('express-rate-limit');

// Global limiter — broad safety net
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // max requests per window per IP
  standardHeaders: true,     // return RateLimit-* headers per RFC 6585
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});

// Stricter limiter for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: { error: 'Too many authentication attempts.' },
});

app.use(globalLimiter);
app.use('/auth', authLimiter);
```

---

### Finding 5 — 🟡 Medium: No Logging or Audit Trail (OWASP A09)

**File:** `app.js` — entirely absent

There is currently no structured request logging. Failed auth attempts, unusual access patterns, and errors are all invisible. This directly violates OWASP A09 (Security Logging and Monitoring Failures).

**Recommendation:** Add `morgan` for HTTP logging and a structured logger (e.g. `pino`) for application events.

```bash
npm install morgan pino pino-pretty
```

```javascript
const morgan = require('morgan');
const pino = require('pino');

const logger = pino({
  level: process.env.LOG_LEVEL ?? 'info',
  redact: ['req.headers.authorization', 'body.password'], // never log sensitive fields
});

// HTTP request logging
app.use(morgan('combined', {
  stream: { write: (msg) => logger.info(msg.trim()) },
}));

// Usage in route handler
app.get('/users', requireAuth, (req, res) => {
  logger.info({ userId: req.user.sub, action: 'list_users' }, 'User list accessed');
  res.json([...]);
});

// Log authentication failures explicitly
function requireAuth(req, res, next) {
  // ... verify token ...
  } catch (err) {
    logger.warn({ ip: req.ip, path: req.path }, 'Authentication failure');
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
}
```

---

### Finding 6 — 🟡 Medium: No Body Parsing Limits or Input Validation

**File:** `app.js` — no `express.json()` configured at all

The app has no body parser configured, which means any future `POST`/`PUT` route added by a developer will either silently fail or be added without size limits — a common source of payload-based DoS attacks. When a body parser is added later, it should have explicit size limits and validation.

**Recommendation:**

```javascript
// Always set a payload size limit — the default (100kb) is often too large or too small
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));
```

For any route that accepts user input, use a schema validation library:

```bash
npm install zod
```

```javascript
const { z } = require('zod');

const CreateUserSchema = z.object({
  name:  z.string().min(1).max(100).trim(),
  email: z.string().email().max(254).toLowerCase(),
  role:  z.enum(['user', 'admin']).default('user'),
});

app.post('/users', requireAuth, (req, res) => {
  const result = CreateUserSchema.safeParse(req.body);
  if (!result.success) {
    return res.status(400).json({
      error: 'Validation failed',
      details: result.error.flatten(),
    });
  }
  const safeData = result.data; // fully typed and sanitized
  // proceed with safeData, never raw req.body
});
```

---

### Finding 7 — 🟡 Medium: No Global Error Handler

**File:** `app.js` — entirely absent

Without a centralized error handler, Express will fall back to its default behavior, which sends stack traces and internal details to the client in development mode — and in production can cause unhandled promise rejections to crash the process.

**Recommendation:** Always add a four-argument error handler as the **last** middleware.

```javascript
// Must be registered AFTER all routes
app.use((err, req, res, next) => {
  const status = err.status ?? err.statusCode ?? 500;

  // Log the full error internally
  logger.error({ err, path: req.path, method: req.method }, 'Unhandled error');

  // Never leak stack traces or internal messages to the client
  res.status(status).json({
    error: status < 500
      ? err.message                   // safe to surface 4xx messages
      : 'An internal error occurred', // never surface 5xx details
  });
});
```

---

### Finding 8 — 🟢 Low: Information Disclosure in `/health`

**File:** `app.js`, line 9

Returning `new Date().toISOString()` exposes the server's local clock with millisecond precision. This aids timing-based attacks and can reveal timezone or infrastructure details.

**Recommendation:** Return only what consumers actually need.

```javascript
app.get('/health', (req, res) => {
  res.json({ status: 'ok' }); // drop the timestamp, or use Unix epoch if uptime tracking is needed
});
```

---

### Finding 9 — 🟢 Low: Full PII Exposure on `/users` (OWASP A02)

**File:** `app.js`, lines 13–18

The `/users` endpoint returns all user records in full, with no filtering, field projection, or pagination. As a data set grows, this becomes both a performance and a data exposure issue. Email addresses are PII and should not be broadcast to all authenticated callers — only those with appropriate roles.

**Recommendation:**

```javascript
app.get('/users', requireAuth, (req, res) => {
  // Role-based field filtering
  const isAdmin = req.user.role === 'admin';

  const users = getUsersFromDB(); // paginated query
  const safeUsers = users.map(u => ({
    id:    u.id,
    name:  u.name,
    ...(isAdmin && { email: u.email }), // only admins see email
  }));

  res.json({
    data: safeUsers,
    pagination: { page: 1, perPage: 20, total: safeUsers.length },
  });
});
```

---

### Hardened `app.js` — Consolidated Example

```javascript
'use strict';

require('dotenv').config(); // load from .env, which is in .gitignore

const express  = require('express');
const helmet   = require('helmet');
const cors     = require('cors');
const morgan   = require('morgan');
const rateLimit = require('express-rate-limit');
const pino     = require('pino');

const { requireAuth } = require('./auth.middleware');

const app    = express();
const logger = pino({ redact: ['req.headers.authorization'] });

// ── Security headers (must be first) ──────────────────────────────────────────
app.use(helmet());
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') ?? [],
  credentials: true,
}));

// ── Rate limiting ──────────────────────────────────────────────────────────────
app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100 }));

// ── Body parsing with size limits ─────────────────────────────────────────────
app.use(express.json({ limit: '10kb' }));

// ── Request logging ───────────────────────────────────────────────────────────
app.use(morgan('combined', { stream: { write: m => logger.info(m.trim()) } }));

// ── Routes ────────────────────────────────────────────────────────────────────
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

app.get('/users', requireAuth, (req, res) => {
  logger.info({ userId: req.user.sub }, 'list_users');
  res.json({ data: [{ id: 1, name: 'Alice' }], pagination: { page: 1 } });
});

// ── Global error handler (must be last) ───────────────────────────────────────
app.use((err, req, res, _next) => {
  logger.error({ err }, 'unhandled_error');
  const status = err.status ?? 500;
  res.status(status).json({
    error: status < 500 ? err.message : 'An internal error occurred',
  });
});

const PORT = Number(process.env.PORT) ?? 3000;
app.listen(PORT, () => logger.info({ port: PORT }, 'server_started'));

module.exports = app;
```

---

### Recommended Dependencies

```bash
npm install helmet cors morgan pino express-rate-limit zod jsonwebtoken dotenv
npm install --save-dev eslint eslint-plugin-security   # static analysis
npx audit                                              # check for known CVEs in deps
```

---

### Prioritized Action Plan

1. **Immediately** — Add `.env*` to `.gitignore`. Rotate any real credentials that have touched the existing `.env.test` pattern.
2. **Before first deployment** — Add `helmet`, authentication middleware, and rate limiting.
3. **Before handling user data** — Add input validation (Zod schemas) and the global error handler.
4. **Ongoing** — Enable structured logging, run `npm audit` in CI, and add `eslint-plugin-security` to your lint pipeline.

