'use strict';

/**
 * app.hardened.js — Security-hardened version of app.js
 *
 * Dependencies to add to package.json:
 *   express, helmet, cors, express-rate-limit, express-validator, jsonwebtoken
 */

const express = require('express');
const helmet  = require('helmet');
const cors    = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const jwt     = require('jsonwebtoken');

// ---------------------------------------------------------------------------
// 1. Fail-fast: crash immediately if required secrets are absent
// ---------------------------------------------------------------------------
const REQUIRED_ENV_VARS = ['JWT_SECRET'];
for (const key of REQUIRED_ENV_VARS) {
  if (!process.env[key]) {
    console.error(`FATAL: Missing required environment variable: ${key}`);
    process.exit(1);
  }
}

const app = express();

// ---------------------------------------------------------------------------
// 2. Security headers (removes X-Powered-By, sets CSP, HSTS, etc.)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 3. Explicit, restrictive CORS policy
// ---------------------------------------------------------------------------
app.use(cors({
  origin: process.env.ALLOWED_ORIGIN || 'https://yourdomain.com',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
}));

// ---------------------------------------------------------------------------
// 4. Body parsing with payload size cap (prevents DoS via large bodies)
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 5. Global rate limiter — 100 requests per 15 minutes per IP
// ---------------------------------------------------------------------------
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(globalLimiter);

// ---------------------------------------------------------------------------
// 6. Authentication middleware
// ---------------------------------------------------------------------------
function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Expect: Bearer <token>

  if (!token) {
    return res.status(401).json({ error: 'Authentication required.' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, decoded) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token.' });
    }
    req.user = decoded;
    next();
  });
}

// ---------------------------------------------------------------------------
// 7. Routes
// ---------------------------------------------------------------------------

// Health check — public, no auth required
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users list — protected; returns only non-sensitive fields
app.get('/users', requireAuth, (req, res) => {
  // TODO: replace with a real parameterized DB query, e.g.:
  //   const users = await db.query('SELECT id, name FROM users');
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  // Only expose fields the caller actually needs (drop PII like email)
  res.json(users.map(({ id, name }) => ({ id, name })));
});

// Example: future POST /users with full input validation
app.post('/users', requireAuth, [
  body('name')
    .isString()
    .trim()
    .isLength({ min: 1, max: 100 })
    .escape(),
  body('email')
    .isEmail()
    .normalizeEmail(),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Safe to use req.body.name and req.body.email here
  res.status(201).json({ message: 'User created.' });
});

// ---------------------------------------------------------------------------
// 8. Centralized error handler — must be registered last
//    Never leaks stack traces or internal details to the client
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error({
    message: err.message,
    stack:   err.stack,
    path:    req.path,
    method:  req.method,
    ip:      req.ip,
  });

  const status  = err.status || 500;
  const message = status < 500 ? err.message : 'Internal server error.';
  res.status(status).json({ error: message });
});

// ---------------------------------------------------------------------------
// 9. Handle unhandled rejections — log and exit so the process manager
//    (PM2, Kubernetes, systemd) can restart cleanly
// ---------------------------------------------------------------------------
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled promise rejection:', reason);
  process.exit(1);
});

// ---------------------------------------------------------------------------
// 10. Only bind the port when run directly (keeps the module testable)
// ---------------------------------------------------------------------------
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

