    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
}

// Public route — no auth needed
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Protected route
app.get('/users', requireAuth, (req, res) => {
  // ... return users
});
```

---

## Finding #2 — No Rate Limiting (OWASP A04 / Unrestricted Resource Consumption)

**Severity: 🔴 Critical**

There is no rate limiting on any endpoint. This opens the server to brute-force attacks, credential stuffing, scraping, and denial-of-service via request flooding.

**Recommendation:**

```js
const rateLimit = require('express-rate-limit'); // npm install express-rate-limit

// Global limiter for all routes
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15-minute window
  max: 100,                  // max 100 requests per IP per window
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests. Please try again later.' },
});

// Stricter limiter for sensitive endpoints
const sensitiveRouteLimiter = rateLimit({
  windowMs: 60 * 1000, // 1-minute window
  max: 10,
  message: { error: 'Too many requests to this endpoint.' },
});

app.use(globalLimiter);
app.get('/users', sensitiveRouteLimiter, requireAuth, (req, res) => { ... });
```

---

## Finding #3 — Missing Security Headers (OWASP A05)

**Severity: 🟠 High**

Express, by default, sends an `X-Powered-By: Express` header (fingerprinting) and omits all defensive headers (`Content-Security-Policy`, `X-Frame-Options`, `Strict-Transport-Security`, etc.). This makes the server easier to target and exploit via clickjacking, MIME sniffing, and cross-site attacks.

**Recommendation:**

```js
const helmet = require('helmet'); // npm install helmet

app.use(helmet()); // Sets 11 security headers in one call, including:
                  //   Content-Security-Policy
                  //   X-Frame-Options: SAMEORIGIN
                  //   X-Content-Type-Options: nosniff
                  //   Strict-Transport-Security
                  //   Referrer-Policy
                  // and removes X-Powered-By automatically

// Optionally tune CSP for your specific needs:
app.use(
  helmet.contentSecurityPolicy({
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc:  ["'self'"],
      objectSrc:  ["'none'"],
      upgradeInsecureRequests: [],
    },
  })
);
```

---

## Finding #4 — No Input Validation or Sanitization (OWASP A03)

**Severity: 🟠 High**

The current routes accept no query parameters, but this pattern will scale into routes that do. There is no validation framework in place. Future routes that accept `req.query`, `req.params`, or `req.body` will be vulnerable to injection (NoSQL, SQL, path traversal, prototype pollution) without a validation layer.

**Recommendation — establish the pattern now:**

```js
const { query, param, validationResult } = require('express-validator'); // npm install express-validator

// Example: validated /users route with query filtering
app.get(
  '/users',
  requireAuth,
  [
    query('page').optional().isInt({ min: 1 }).toInt(),
    query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    query('email').optional().isEmail().normalizeEmail(),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // safe to use req.query.page, req.query.email, etc.
  }
);

// Example: validated /users/:id route
app.get(
  '/users/:id',
  requireAuth,
  [param('id').isInt({ min: 1 }).toInt()],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // req.params.id is a safe integer
  }
);
```

---

## Finding #5 — No Request Body Parsing Controls (OWASP A03 / DoS)

**Severity: 🟠 High**

There is no `express.json()` or `express.urlencoded()` middleware, and no body-size limit. When body parsing is added in the future, an attacker can send arbitrarily large payloads to exhaust memory and CPU.

**Recommendation:**

```js
// Enforce strict body size limits — tune to your actual use case
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
```

---

## Finding #6 — Hardcoded, Inline Data (OWASP A02 / Data Exposure)

**Severity: 🟡 Medium**

User records including emails are hardcoded inline. This is a development antipattern that commonly leads to real PII or credentials being left in source code when it transitions to a real data source, and the PII is returned to any unauthenticated caller.

**Recommendation:**

```js
// users.repository.js  — separate data access cleanly from routing
async function getUserById(id) {
  // Use parameterized queries — never string interpolation
  const result = await db.query('SELECT id, name, email FROM users WHERE id = $1', [id]);
  return result.rows[0] ?? null;
}

// In the route: only return fields the caller is authorized to see
app.get('/users/:id', requireAuth, async (req, res) => {
  const user = await getUserById(req.params.id);
  if (!user) return res.status(404).json({ error: 'Not found' });

  // Strip sensitive fields before sending
  const { password_hash, mfa_secret, ...safeFields } = user;
  res.json(safeFields);
});
```

---

## Finding #7 — No Error Handling or Logging (OWASP A09)

**Severity: 🟡 Medium**

There is no global error handler. Unhandled promise rejections or thrown errors will either crash the process or cause Express to leak a full stack trace to the client. Neither outcome is acceptable in production.

**Recommendation:**

```js
const pino = require('pino'); // npm install pino  — structured, fast logging
const logger = pino({ level: process.env.LOG_LEVEL || 'info' });

// Async wrapper to catch errors from async route handlers
const asyncHandler = (fn) => (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next);

app.get('/users', requireAuth, asyncHandler(async (req, res) => {
  const users = await userRepository.getAll();
  res.json(users);
}));

// Global error handler — MUST be registered last, with 4 arguments
app.use((err, req, res, next) => {
  // Log the full error internally — never send it to the client
  logger.error({ err, path: req.path, method: req.method }, 'Unhandled error');

  // Send a generic message externally
  res.status(err.status || 500).json({ error: 'An unexpected error occurred.' });
});

// Catch unhandled rejections at the process level
process.on('unhandledRejection', (reason) => {
  logger.error({ reason }, 'Unhandled promise rejection');
});
```

---

## Finding #8 — Secret Management (OWASP A02)

**Severity: 🔴 Critical**

A `.env.test` file is present in the working directory containing multiple high-value credentials. Any of the following would result in full compromise:
- Committing this file to a git repository (even a private one)
- A directory-traversal or path-disclosure vulnerability exposing it
- Broad filesystem permissions allowing other processes to read it

**Recommendation:**

```bash
# 1. Add to .gitignore immediately
echo ".env*" >> .gitignore
echo "!.env.example" >> .gitignore

# 2. Rotate every credential in that file — assume compromise

# 3. Use a secrets manager in production, not flat files:
#    AWS Secrets Manager, HashiCorp Vault, GCP Secret Manager, etc.
```

```js
// In app.js: load env only in non-production environments
if (process.env.NODE_ENV !== 'production') {
  require('dotenv').config(); // npm install dotenv
}

// Always access secrets through environment variables, never hardcode them
const jwtSecret = process.env.JWT_SECRET;
if (!jwtSecret) throw new Error('JWT_SECRET environment variable is required');
```

---

## Finding #9 — No CORS Configuration (OWASP A05)

**Severity: 🟡 Medium**

There is no CORS policy. By default, Express does not add CORS headers, but if this API is later proxied or called from a browser, a misconfigured CORS wildcard (`*`) is a common mistake that would allow any origin to make credentialed requests.

**Recommendation:**

```js
const cors = require('cors'); // npm install cors

const allowedOrigins = (process.env.ALLOWED_ORIGINS || '').split(',').filter(Boolean);

app.use(cors({
  origin: (origin, callback) => {
    // Allow requests with no origin (e.g., server-to-server, curl)
    if (!origin) return callback(null, true);
    if (allowedOrigins.includes(origin)) return callback(null, true);
    callback(new Error(`CORS policy: origin '${origin}' is not allowed`));
  },
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
}));
```

---

## Finding #10 — `/health` Endpoint Information Disclosure

**Severity: 🟢 Low**

The `/health` endpoint returns a server-side timestamp. While low-risk in isolation, health endpoints can be used to fingerprint uptime, confirm a target is live, or chain with other attacks. At minimum, it should be excluded from public exposure or access-controlled.

**Recommendation:**

```js
// Option A: Restrict to internal networks only
app.get('/health', (req, res) => {
  const ip = req.ip || req.socket.remoteAddress;
  const isInternal = ip === '127.0.0.1' || ip === '::1' || ip?.startsWith('10.');
  if (!isInternal) return res.status(404).end(); // Don't reveal existence

  res.json({ status: 'ok' }); // Omit timestamp to reduce information leakage
});

// Option B: Serve a minimal liveness probe (no data) publicly,
// and a richer readiness probe internally only
app.get('/health/live',  (_req, res) => res.status(204).end());
app.get('/health/ready', requireInternalAuth, (req, res) => {
  res.json({ status: 'ok', uptime: process.uptime() });
});
```

---

## Summary Table

| # | Finding | OWASP Category | Severity |
|---|---------|---------------|----------|
| 1 | No authentication or authorization | A01 Broken Access Control | 🔴 Critical |
| 2 | No rate limiting | A04 Unrestricted Resource Consumption | 🔴 Critical |
| 3 | Missing security headers | A05 Security Misconfiguration | 🟠 High |
| 4 | No input validation or sanitization | A03 Injection | 🟠 High |
| 5 | No body parsing controls / no size limit | A03 / DoS | 🟠 High |
| 6 | Hardcoded PII, no data access layer | A02 Cryptographic / Data Exposure | 🟡 Medium |
| 7 | No error handling or structured logging | A09 Security Logging Failures | 🟡 Medium |
| 8 | Credentials in `.env.test` file | A02 Cryptographic / Data Exposure | 🔴 Critical |
| 9 | No CORS policy | A05 Security Misconfiguration | 🟡 Medium |
| 10 | `/health` information disclosure | A05 Security Misconfiguration | 🟢 Low |

## Prioritized Remediation Order

1. **Immediately:** Rotate all credentials in `.env.test` and add `*.env*` to `.gitignore` — assume the file has already been seen.
2. **Before any deployment:** Add authentication (`jsonwebtoken`) and rate limiting (`express-rate-limit`).
3. **Before any deployment:** Add `helmet` for security headers and `express-validator` for input validation.
4. **Short-term:** Add a global error handler with structured logging, enforce body size limits, and configure CORS explicitly.
5. **Ongoing:** Establish a data access layer that uses parameterized queries, strip sensitive fields from responses, and adopt a secrets manager for all environments.

