app.use((err, req, res, next) => {
  // Log the full error internally:
  logger.error({ event: 'unhandled_error', message: err.message, stack: err.stack });

  // Return a safe, generic message to the client:
  res.status(err.status ?? 500).json({
    error: process.env.NODE_ENV === 'production'
      ? 'An unexpected error occurred.'
      : err.message, // only in dev
  });
});

// Catch unhandled promise rejections:
process.on('unhandledRejection', (reason) => {
  logger.error({ event: 'unhandled_rejection', reason });
  process.exit(1); // let process manager (PM2/k8s) restart cleanly
});
```

