#### 1. No Authentication or Authorization on Any Route
**OWASP A01 – Broken Access Control**

Every route is fully public. `/users` returns user PII with zero authentication. As the app grows, this pattern will be copied to sensitive routes.

```js
// ❌ Current — anyone can call /users
app.get('/users', (req, res) => {
  res.json([...]);
});
```

**Fix:** Add an authentication middleware from the start so all routes are protected by default, and public routes are explicitly opted out.

```js
// ✅ JWT auth middleware
const jwt = require('jsonwebtoken');

function requireAuth(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or invalid Authorization header' });
  }
  try {
    req.user = jwt.verify(authHeader.slice(7), process.env.JWT_SECRET);
    next();
  } catch {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
}

// Apply globally, then explicitly allow public routes
app.use(requireAuth);
app.get('/health', skipAuth, healthHandler); // public
app.get('/users', requireAuth, usersHandler); // protected
```

