## 🔒 Security Review: `app.js`

**Overall Risk: MEDIUM-HIGH** — The app is minimal today, but has foundational security gaps that will cause serious vulnerabilities as it grows. Many issues are architectural and need to be fixed *before* adding features, not after.

---

### Finding 1 — 🔴 Missing Authentication & Authorization (OWASP A01, A07)

**The `/users` endpoint returns user data with zero authentication.** Any anonymous request gets a full user list. There is no token, session, or API key check anywhere.

```js
// ❌ CURRENT — completely open
app.get('/users', (req, res) => {
  res.json([{ id: 1, name: 'Alice', email: 'alice@example.com' }, ...]);
});
```

**Fix:** Add an authentication middleware. Here's a JWT-based example:

```js
const jwt = require('jsonwebtoken');

function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // "Bearer <token>"

  if (!token) {
    return res.status(401).json({ error: 'Missing authentication token' });
  }

  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (err) {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
}

// ✅ Protected route
app.get('/users', requireAuth, (req, res) => {
  res.json([...]);
});
```

---

### Finding 2 — 🔴 No Input Validation Anywhere (OWASP A03)

The app uses `express` but never parses or validates request bodies or query parameters. When features like search, filtering, or user creation are added (which is inevitable), there will be no validation layer in place — creating an injection surface from day one.

**Fix:** Install and configure a validation library *now*, before routes grow:

```js
const express = require('express');
const { query, body, validationResult } = require('express-validator');

app.use(express.json()); // Required to parse JSON bodies

// Middleware to reject requests that fail validation
function validate(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
}

// Example: future search endpoint with validation built in
app.get('/users',
  requireAuth,
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
  validate,
  (req, res) => {
    const { limit = 20, offset = 0 } = req.query;
    // safe to use limit/offset now
  }
);
```

---

### Finding 3 — 🔴 No Security Headers (OWASP A05)

Express sends no security headers by default. This exposes users to XSS, clickjacking, MIME-sniffing, and other browser-based attacks.

```bash
# Current response headers are dangerously bare:
# X-Powered-By: Express   ← actively advertises your stack
# (no Content-Security-Policy)
# (no X-Frame-Options)
# (no X-Content-Type-Options)
```

**Fix:** Add `helmet` — it sets 14 security headers in one line:

```js
const helmet = require('helmet');

// ✅ Add immediately after app = express()
app.use(helmet());

// For fine-grained control:
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
    },
  },
  hsts: {
    maxAge: 31536000,       // 1 year
    includeSubDomains: true,
    preload: true,
  },
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
}));
```

---

### Finding 4 — 🟠 Information Leakage via `X-Powered-By` Header (OWASP A05)

Express advertises itself with `X-Powered-By: Express` on every response, helping attackers fingerprint your stack and target known Express/Node.js CVEs.

```js
// ❌ Express does this by default — free recon for attackers

// ✅ Fix (helmet does this too, but you can do it standalone):
app.disable('x-powered-by');
```

---

### Finding 5 — 🟠 No Rate Limiting (OWASP A04)

The `/users` and `/health` endpoints have no rate limiting. This enables:
- Brute-force attacks on future auth endpoints
- Scraping of user data
- Denial-of-service via request flooding

```js
const rateLimit = require('express-rate-limit');

// ✅ Global baseline limiter
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // max requests per window per IP
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(globalLimiter);

// ✅ Stricter limiter for sensitive endpoints (e.g., future /login)
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: { error: 'Too many login attempts.' },
});
app.post('/login', authLimiter, loginHandler);
```

---

### Finding 6 — 🟠 Hardcoded & Static Data Will Become a Data Exposure Risk (OWASP A02)

The user list is currently hardcoded, but the structure telegraphs that real PII (emails, etc.) will live here soon. When it moves to a real database, there's no field-filtering layer, meaning sensitive fields (passwords, tokens, internal IDs) could be accidentally serialized into API responses.

**Fix:** Establish a response serialization pattern now:

```js
// ✅ Explicit allowlist of fields returned to clients
function serializeUser(user) {
  return {
    id: user.id,
    name: user.name,
    email: user.email,
    // ← passwordHash, mfaSecret, internalFlags are NEVER included
  };
}

app.get('/users', requireAuth, (req, res) => {
  const users = db.getAllUsers(); // future DB call
  res.json(users.map(serializeUser));
});
```

---

### Finding 7 — 🟠 No CORS Policy (OWASP A05)

No CORS headers are set. Depending on deployment, this either blocks all cross-origin requests (breaking legitimate frontends) or, if misconfigured later, opens the API to cross-origin attacks.

```js
const cors = require('cors');

// ✅ Explicit allowlist — never use cors() with no config in production
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') ?? ['https://yourdomain.com'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400, // cache preflight for 24 hours
}));
```

---

### Finding 8 — 🟡 No Centralized Error Handler (OWASP A05)

Unhandled errors in Express will either crash the process or leak stack traces to clients. There is currently no error-handling middleware.

```js
// ✅ Add at the very END of all route definitions
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

app.use((err, req, res, next) => {
  // Log internally with full detail
  console.error({
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
  });

  // Return sanitized error to client — no stack traces, no internal paths
  const status = err.status ?? 500;
  res.status(status).json({
    error: status === 500 ? 'Internal server error' : err.message,
  });
});
```

---

### Finding 9 — 🟡 No Request Body Size Limit (OWASP A04)

When `express.json()` is added (which it must be), the default body size limit is 100kb. For most APIs this should be far lower, and for file-upload endpoints far higher — but intentional. Without explicit limits, large payloads can be used in denial-of-service attacks.

```js
// ✅ Set explicit, intentional limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
```

---

### Finding 10 — 🟡 `/health` Endpoint Leaks Server Timing Info

The health endpoint returns a live `timestamp`, which helps attackers correlate requests and probe server behavior. Health endpoints should also be protected or at minimum not enriched unnecessarily.

```js
// ❌ Current — returns live server timestamp
res.json({ status: 'ok', timestamp: new Date().toISOString() });

// ✅ Minimal health check — no operational detail exposed publicly
res.json({ status: 'ok' });

// ✅ OR gate the detailed version behind internal network / auth checks
if (req.ip === '127.0.0.1' || req.headers['x-internal-token'] === process.env.HEALTH_TOKEN) {
  res.json({ status: 'ok', timestamp: new Date().toISOString(), uptime: process.uptime() });
} else {
  res.json({ status: 'ok' });
}
```

---

## ✅ Recommended `app.js` — Hardened Baseline

Here is a consolidated, secured version of the file incorporating all fixes:

```js
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');

const app = express();

// ── 1. Disable fingerprinting ──────────────────────────────────────────────
app.disable('x-powered-by');

// ── 2. Security headers ────────────────────────────────────────────────────
app.use(helmet());

// ── 3. CORS ────────────────────────────────────────────────────────────────
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') ?? [],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
}));

// ── 4. Body parsing with size limits ──────────────────────────────────────
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ── 5. Rate limiting ───────────────────────────────────────────────────────
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
}));

// ── 6. Auth middleware ─────────────────────────────────────────────────────
function requireAuth(req, res, next) {
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Missing token' });
  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch {
    res.status(403).json({ error: 'Invalid or expired token' });
  }
}

// ── 7. Validation helper ───────────────────────────────────────────────────
function validate(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });
  next();
}

// ── 8. User serializer ─────────────────────────────────────────────────────
function serializeUser(user) {
  return { id: user.id, name: user.name, email: user.email };
}

// ── Routes ─────────────────────────────────────────────────────────────────
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

app.get('/users',
  requireAuth,
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
  validate,
  (req, res) => {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];
    res.json(users.map(serializeUser));
  }
);

// ── Error handlers (must be last) ──────────────────────────────────────────
app.use((req, res) => res.status(404).json({ error: 'Not found' }));

app.use((err, req, res, next) => {
  console.error({ message: err.message, stack: err.stack, url: req.url });
  const status = err.status ?? 500;
  res.status(status).json({
    error: status === 500 ? 'Internal server error' : err.message,
  });
});

app.listen(3000, () => console.log('Server running on port 3000'));
module.exports = app;
```

