## Finding 2 — 🔴 CRITICAL: No Authentication or Authorization (OWASP A01 – Broken Access Control)

**File:** `app.js`, lines 12–17

The `/users` endpoint returns user data (names, emails) with **zero authentication**. Any anonymous HTTP client can retrieve it. There is also no authorization layer — no concept of roles, ownership, or scopes exists anywhere.

```js
// ❌ Current — fully open
app.get('/users', (req, res) => {
  res.json([{ id: 1, name: 'Alice', email: 'alice@example.com' }, ...]);
});
```

**Fix — Add a JWT authentication middleware:**
```js
const jwt = require('jsonwebtoken');

// Middleware: verify Bearer token on every protected route
function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed Authorization header' });
  }
  const token = authHeader.slice(7);
  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
}

// Middleware: restrict to specific roles
function requireRole(...roles) {
  return (req, res, next) => {
    if (!roles.includes(req.user?.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
}

// ✅ Protected route
app.get('/users', requireAuth, requireRole('admin'), (req, res) => {
  res.json(users);
});
```

