## Finding 3 — 🔴 CRITICAL: No Input Validation on Any Parameter (OWASP A03 – Injection)

**File:** `app.js`

There is currently no middleware to parse or validate request bodies, query strings, or path parameters. When database queries or business logic are added (the natural next step), raw unvalidated input will flow directly into them, enabling:
- **SQL Injection** via query parameters passed to a DB driver
- **NoSQL Injection** (e.g., MongoDB `$where` operator abuse)
- **Command Injection** if any input reaches `exec()`/`spawn()`

```js
// ❌ What will happen without validation guards:
app.get('/users/:id', async (req, res) => {
  // If id = "1 OR 1=1", this becomes a SQL injection vector
  const user = await db.query(`SELECT * FROM users WHERE id = ${req.params.id}`);
  res.json(user);
});
```

**Fix — Body parsing + schema validation with `zod` or `joi`:**
```js
const { z } = require('zod');
const express = require('express');
app.use(express.json({ limit: '10kb' })); // parse bodies AND cap size (see Finding 5)

// Define strict schemas
const UserIdSchema = z.object({
  id: z.string().regex(/^\d+$/, 'ID must be numeric').transform(Number),
});

const CreateUserSchema = z.object({
  name:  z.string().min(1).max(100).trim(),
  email: z.string().email().max(255).toLowerCase(),
  role:  z.enum(['user', 'admin']),
});

// Reusable validation middleware factory
function validate(schema, source = 'body') {
  return (req, res, next) => {
    const result = schema.safeParse(req[source]);
    if (!result.success) {
      return res.status(400).json({
        error: 'Validation failed',
        details: result.error.flatten(),
      });
    }
    req.validated = result.data; // attach clean data
    next();
  };
}

// ✅ Safe parameterized query + validated input
app.get('/users/:id',
  requireAuth,
  validate(UserIdSchema, 'params'),
  async (req, res) => {
    const { id } = req.validated;
    const user = await db.query('SELECT * FROM users WHERE id = $1', [id]); // parameterized
    if (!user) return res.status(404).json({ error: 'Not found' });
    res.json(user);
  }
);
```

