// ✅ Detailed health check restricted to internal callers
app.get('/health/details', requireAuth, requireRole('admin'), async (req, res) => {
  const dbOk = await checkDatabaseConnection();
  res.json({
    status: dbOk ? 'ok' : 'degraded',
    uptime: process.uptime(),
    timestamp: new Date().toISOString(),
