  maxAge:           86400, // preflight cache: 24 h
}));
```

---

## Finding 6 — No Request Body Parsing or Input Validation
**Severity: 🟡 Medium | OWASP A03: Injection**

There is no `express.json()` middleware and no input validation library. Any future route that accepts a body has no protection against oversized payloads, malformed JSON, or injected data. This is the precondition for injection attacks (SQL, NoSQL, command).

**Fix:** Add body parsing with size limits and schema validation on every input boundary.

```javascript
// Body parsing with an explicit size cap
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Example: validated POST /users route using zod
const { z } = require('zod');

const createUserSchema = z.object({
  name:  z.string().min(1).max(100).regex(/^[\w\s'-]+$/),
  email: z.string().email().max(254),
  role:  z.enum(['user', 'moderator']), // never accept 'admin' from user input
});

app.post('/users', requireAuth, requireRole('admin'), (req, res) => {
  const result = createUserSchema.safeParse(req.body);
  if (!result.success) {
    // Return validation errors but nothing internal
    return res.status(400).json({ error: 'Invalid input', details: result.error.flatten() });
  }
  // result.data is now safe to use
  const { name, email, role } = result.data;
  // ... persist to database using parameterized queries
});
```

---

## Finding 7 — Verbose Error Disclosure in Health Endpoint
**Severity: 🟡 Medium | OWASP A05: Security Misconfiguration**

`/health` currently returns `new Date().toISOString()` — low risk on its own, but the pattern of exposing internal state should be locked down before the codebase grows. More critically, there is no global error handler, meaning any unhandled exception will expose an Express stack trace to the client.

**Fix:** Add a global error handler that sanitizes output by environment.

```javascript
// routes/health.js — minimal, non-leaking health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok' }); // no timestamp, no version, no env details
});

// --- Place this LAST, after all routes ---

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Global error handler — must have exactly 4 parameters for Express to recognise it
app.use((err, req, res, next) => { // eslint-disable-line no-unused-vars
  // Log full error internally (use a structured logger like pino, not console)
  logger.error({ err, url: req.url, method: req.method }, 'Unhandled error');

  // Never leak stack traces or internal messages to the client
  const isProduction = process.env.NODE_ENV === 'production';
  res.status(err.status ?? 500).json({
    error: isProduction ? 'Internal server error' : err.message,
  });
});
```

---

## Finding 8 — Hardcoded Port and No Graceful Shutdown
**Severity: 🟢 Low | OWASP A05: Security Misconfiguration**

Port `3000` is hardcoded and `app.listen` has no shutdown handler. In production this prevents zero-downtime deploys, causes connection drops on restart, and can leave sockets in a stuck state.

**Fix:** Read port from environment and implement graceful shutdown.

```javascript
const { env } = require('./config');

const server = app.listen(env.PORT, () => {
  logger.info(`Server listening on port ${env.PORT}`);
});

// Graceful shutdown — give in-flight requests time to complete
function shutdown(signal) {
  logger.info(`${signal} received — shutting down gracefully`);
  server.close(() => {
    logger.info('All connections closed. Exiting.');
    process.exit(0);
  });
  // Force exit if still open after 10 s
  setTimeout(() => process.exit(1), 10_000).unref();
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));
process.on('uncaughtException',  (err) => { logger.fatal(err, 'Uncaught exception');  process.exit(1); });
process.on('unhandledRejection', (err) => { logger.fatal(err, 'Unhandled rejection'); process.exit(1); });
```

